"""The edits made to the generated plan at approval, as a script so they are reproducible.

    python3 plans/approve_ja.py    # reads plans/generated-raw.json, writes plans/interview-ja.json
"""
import json, pathlib

HERE = pathlib.Path(__file__).parent
raw = json.loads((HERE / "generated-raw.json").read_text())

NOTE = (
    "Generated by `--plan brief.md` with z-ai/glm-5.3-flash (second attempt; the first wrote "
    "done_threshold 1, out of bounds), then approved with these edits, applied by plans/approve_ja.py. "
    "(1) Every rubric came back best-first; the program reads level 0 as the worst, so each "
    "question's rubric and the fit rubric were reversed. The fit rubric was also reordered so that "
    "'cannot be assessed' sits above 'irreconcilable conflict'. "
    "(2) per_dimension 1 -> 2, min_q 5 -> 8, max_q 8 -> 12, reserve_early 1 (unchanged): as written, "
    "coverage was met by the fourth answer and the budget ran to eight, so the judge chose almost "
    "nothing and `done` could not vary. Now 4 dimensions owe 8 answers, the budget is 12, and the "
    "pool is 16. (3) done_threshold 0.95 -> 0.5: the model's two attempts wrote 1 and then the "
    "bound's maximum, neither a considered number; 0.5 is the same provisional value the earlier "
    "50-interview plan ran under. (4) Six questions added by the approver, written in the same "
    "style, so the pool exceeds the budget and some questions go unasked: two per technical "
    "dimension. A second generated draft failed validation twice and was not used. "
    "(5) ui text -> textarea, with text also allowed: these questions want prose. "
    "(6) One typo fixed in rust_readiness (聞かせます -> 聞かせてください). "
    "(7) done.true: 'at least once' -> 'at least twice', to match per_dimension. "
    "Nothing else was changed; dimension names and weights are the model's.")

plan = dict(raw)
plan["policy"] = {**raw["policy"], "per_dimension": 2, "reserve_early": 1, "min_q": 8,
                  "max_q": 12, "done_threshold": 0.5}
plan["done"] = {"true": raw["done"]["true"].replace("最低1回ずつ", "最低2回ずつ"),
                "false": raw["done"]["false"]}
fit = raw["fit"]["rubric"]           # generated order: aligned, conditional, conflict, cannot assess
plan["fit"] = {"rubric": [fit[2], fit[3], fit[1], fit[0]]}

def approve(q):
    q = dict(q)
    q["rubric"] = list(reversed(q["rubric"]))
    q["ui"], q["ui_options"] = "textarea", ["textarea", "text"]
    if q["id"] == "rust_readiness":
        q["text"] = q["text"].replace("考えも聞かせます。", "考えも聞かせてください。")
    return q

D_JAVA, D_RUST, D_MONEY = (raw["dimensions"][i]["name"] for i in (0, 1, 2))

