plan["source"] = {**raw["source"], "note": NOTE}
(HERE / "interview-ja.json").write_text(json.dumps(plan, ensure_ascii=False, indent=1) + "\n",
                                        encoding="utf-8")
print(f"wrote interview-ja.json: {len(plan['questions'])} questions")
